INSERT INTO "central_associations" ("id", "triggerKind", "triggerKey", "triggerLabel", "adviceEan", "adviceLabel", "sentence", "sortOrder", "createdByName", "updatedAt") VALUES
  ('atc01_01_d10ba01', 'ATC', 'atc:D10BA01', 'D10BA01 · Isotrétinoïne orale', '3282770100891', 'Avène Cleanance Hydra Soin réparateur ultra-apaisant', 'Ce traitement peut dessécher la peau. Un soin hydratant adapté aide à limiter les tiraillements dès le début du traitement.', 10, 'Série ATC 01 (13/10/2026)', CURRENT_TIMESTAMP),
  ('atc01_02_d10ba01', 'ATC', 'atc:D10BA01', 'D10BA01 · Isotrétinoïne orale', '0000030106659', 'La Roche-Posay Cicaplast Lèvres', 'Pensez à protéger régulièrement vos lèvres : leur dessèchement est fréquent sous ce traitement.', 20, 'Série ATC 01 (13/10/2026)', CURRENT_TIMESTAMP),
  ('atc01_03_d10ba01', 'ATC', 'atc:D10BA01', 'D10BA01 · Isotrétinoïne orale', '0300651507645', 'Systane Ultra sans conservateur', 'Des larmes artificielles peuvent soulager la sécheresse des yeux. Une douleur ou une modification de la vision nécessite un avis médical.', 30, 'Série ATC 01 (13/10/2026)', CURRENT_TIMESTAMP),
  ('atc01_04_d10ba01', 'ATC', 'atc:D10BA01', 'D10BA01 · Isotrétinoïne orale', '3282770100921', 'Avène Cleanance Hydra Crème lavante apaisante', 'Privilégiez un nettoyage doux, sans gommage, pour ne pas accentuer la sécheresse liée au traitement.', 40, 'Série ATC 01 (13/10/2026)', CURRENT_TIMESTAMP),
  ('atc01_05_d10ad03', 'ATC', 'atc:D10AD03', 'D10AD03 · Adapalène', '3282770100891', 'Avène Cleanance Hydra Soin réparateur ultra-apaisant', 'Si votre peau tire ou devient sèche, ajoutez un hydratant adapté et évitez les soins irritants.', 50, 'Série ATC 01 (13/10/2026)', CURRENT_TIMESTAMP),
  ('atc01_06_d10ad53', 'ATC', 'atc:D10AD53', 'D10AD53 · Adapalène + peroxyde de benzoyle', '3337875777797', 'La Roche-Posay Effaclar H Iso-Biome Soin', 'Un hydratant non comédogène peut améliorer le confort de la peau pendant le traitement. Si l''irritation devient importante, faites réévaluer son utilisation.', 60, 'Série ATC 01 (13/10/2026)', CURRENT_TIMESTAMP),
  ('atc01_07_d10ad03', 'ATC', 'atc:D10AD03', 'D10AD03 · Adapalène', '3282770100921', 'Avène Cleanance Hydra Crème lavante apaisante', 'Nettoyez doucement votre peau et séchez-la sans frotter avant d''appliquer votre traitement.', 70, 'Série ATC 01 (13/10/2026)', CURRENT_TIMESTAMP),
  ('atc01_07_d10ad53', 'ATC', 'atc:D10AD53', 'D10AD53 · Adapalène + peroxyde de benzoyle', '3282770100921', 'Avène Cleanance Hydra Crème lavante apaisante', 'Nettoyez doucement votre peau et séchez-la sans frotter avant d''appliquer votre traitement.', 70, 'Série ATC 01 (13/10/2026)', CURRENT_TIMESTAMP),
  ('atc01_08_d10ad03', 'ATC', 'atc:D10AD03', 'D10AD03 · Adapalène', '3401578001234', 'La Roche-Posay Anthelios UVMune 400 Fluide invisible sans parfum SPF50+', 'Évitez les expositions excessives et les UV artificiels. Complétez les vêtements et l''ombre par une protection solaire adaptée.', 80, 'Série ATC 01 (13/10/2026)', CURRENT_TIMESTAMP),
  ('atc01_08_d10ad53', 'ATC', 'atc:D10AD53', 'D10AD53 · Adapalène + peroxyde de benzoyle', '3401578001234', 'La Roche-Posay Anthelios UVMune 400 Fluide invisible sans parfum SPF50+', 'Évitez les expositions excessives et les UV artificiels. Complétez les vêtements et l''ombre par une protection solaire adaptée.', 80, 'Série ATC 01 (13/10/2026)', CURRENT_TIMESTAMP),
  ('atc01_09_d07ab02', 'ATC', 'atc:D07AB02', 'D07AB02 · Hydrocortisone butyrate (Locoid)', '3337875930239', 'La Roche-Posay Lipikar Baume AP+M', 'L''émollient accompagne le traitement de l''eczéma et s''utilise régulièrement, y compris entre les poussées.', 90, 'Série ATC 01 (13/10/2026)', CURRENT_TIMESTAMP),
  ('atc01_09_d07ac01', 'ATC', 'atc:D07AC01', 'D07AC01 · Bétaméthasone (Diprosone)', '3337875930239', 'La Roche-Posay Lipikar Baume AP+M', 'L''émollient accompagne le traitement de l''eczéma et s''utilise régulièrement, y compris entre les poussées.', 90, 'Série ATC 01 (13/10/2026)', CURRENT_TIMESTAMP),
  ('atc01_10_d07ab02', 'ATC', 'atc:D07AB02', 'D07AB02 · Hydrocortisone butyrate (Locoid)', '3337875656764', 'La Roche-Posay Lipikar Huile lavante AP+', 'Pour la toilette, utilisez un lavant doux sans savon, de l''eau tiède et séchez sans frotter.', 100, 'Série ATC 01 (13/10/2026)', CURRENT_TIMESTAMP),
  ('atc01_10_d07ac01', 'ATC', 'atc:D07AC01', 'D07AC01 · Bétaméthasone (Diprosone)', '3337875656764', 'La Roche-Posay Lipikar Huile lavante AP+', 'Pour la toilette, utilisez un lavant doux sans savon, de l''eau tiède et séchez sans frotter.', 100, 'Série ATC 01 (13/10/2026)', CURRENT_TIMESTAMP),
  ('atc01_11_nettoyants-peaux-grasses', 'FAMILY', 'family:fam_nettoyants-peaux-grasses', 'Nettoyants peaux grasses', '3282770100891', 'Avène Cleanance Hydra Soin réparateur ultra-apaisant', 'Votre nettoyant peut être complété par un hydratant si le traitement dessèche votre peau.', 110, 'Série ATC 01 (13/10/2026)', CURRENT_TIMESTAMP),
  ('atc01_12_huiles-et-gels-lavants-p', 'FAMILY', 'family:fam_huiles-et-gels-lavants-peaux-seches', 'Huiles et gels lavants peaux sèches', '3337875930239', 'La Roche-Posay Lipikar Baume AP+M', 'Le lavant assure la toilette ; l''émollient complète la routine pour prendre soin de la peau sèche au quotidien.', 120, 'Série ATC 01 (13/10/2026)', CURRENT_TIMESTAMP)
